/* Auto-generated from the approved policy document. */
window.POLICY_HTML = "<h1><span dir=\"rtl\">سياسة تطوير أساليب التقييم والامتحانات الجامعية</span></h1>\n\n<h2><span dir=\"rtl\">كتاب التقديم</span></h2>\n<p><strong><span dir=\"rtl\"> </span></strong></p>\n<p><span dir=\"rtl\">،</span></p>\n<p><span dir=\"rtl\"><strong> </strong>، .</span></p>\n<p><span dir=\"rtl\">تهدف السياسة إلى بناء منظومة تقييم موحدة المعايير، تضمن صدق الامتحانات وثباتها وعدالتها، وتربطها بمخرجات التعلم ومتطلبات الاعتماد وضمان الجودة، بما ينسجم مع رسالة الجامعة التقنية والتطبيقية.</span></p>\n<p><span dir=\"rtl\">ويتميز المقترح بثلاثة عناصر رئيسية:</span></p>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\"><strong>معايير كمية واضحة</strong> لتوزيع مستويات التفكير في الاختبار، ولمؤشرات التحليل الإحصائي للأسئلة، بما يجعل الجودة قابلة للقياس والمتابعة.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>بنود مستقلة</strong> لأمن الامتحانات ونزاهتها، ولاستخدام أدوات الذكاء الاصطناعي التوليدي، وللعدالة والترتيبات التيسيرية، وللتظلمات.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>ملاحق تنفيذية ونماذج موحدة</strong>، يرافقها دليل تدريبي لأعضاء هيئة التدريس يتضمن أمثلة تطبيقية من التخصصات العلمية والإنسانية.</span></p></li>\n</ol>\n<p><span dir=\"rtl\">ونقترح تطبيق السياسة تجريبياً في عدد من مساقات الكلية خلال الفصل الدراسي الثاني 2026 من التطبيق، ثم تعميمها بعد تقييم نتائجها.</span></p>\n<p><span dir=\"rtl\">وتفضلوا بقبول فائق الاحترام والتقدير،</span></p>\n<p><span dir=\"rtl\"><strong>مقدم المقترح</strong>: د. محمد حوامده</span></p>\n<p><span dir=\"rtl\"><strong>الصفة</strong>: محاضر في قسم نظم المعلومات / كلية تكنولوجيا المعلومات والذكاء الاصطناعي</span></p>\n<h2><span dir=\"rtl\">1. المقدمة والغرض والنطاق والتعريفات</span></h2>\n<h3><span dir=\"rtl\">1.1 المقدمة والمبررات</span></h3>\n<p><span dir=\"rtl\">انطلاقاً من رسالة الجامعة في ضمان جودة التعليم والتعلم والارتقاء بمخرجاتها وتحقيق العدالة بين الطلبة، تبرز الحاجة إلى تطوير أساليب التقييم والامتحانات وفق الاتجاهات الحديثة في القياس والتقويم التربوي.</span></p>\n<p><span dir=\"rtl\">ولا ينبغي أن يقتصر تقييم التحصيل على قياس استرجاع المعلومات، بل يمتد إلى الفهم والتطبيق والتحليل والتقييم وحل المشكلات. وتؤكد المعايير الدولية للاختبارات (AERA, APA, NCME, 2014) أن جودة الاختبار لا تتحدد بنوع الأسئلة، بل بمدى صدقها وثباتها وعدالتها وملاءمتها لمخرجات التعلم.</span></p>\n<p><span dir=\"rtl\">وقد استجدت تحديات لم تكن قائمة من قبل، أبرزها انتشار أدوات الذكاء الاصطناعي التوليدي، والتوسع في الامتحانات الإلكترونية، والظروف الطارئة التي قد تفرض التحول إلى التقييم عن بُعد. وهذا يستدعي سياسة تضبط هذه الجوانب بمعايير واضحة.</span></p>\n<h3><span dir=\"rtl\">1.2 أهداف السياسة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تطوير منظومة التقييم والامتحانات في الجامعة وتوحيد معايير جودتها.</span></p></li>\n<li><p><span dir=\"rtl\">تحقيق التوازن بين قياس المعرفة وقياس المهارات العقلية العليا.</span></p></li>\n<li><p><span dir=\"rtl\">تعزيز موضوعية التصحيح وتقليل التحيز والأخطاء البشرية.</span></p></li>\n<li><p><span dir=\"rtl\">تحقيق العدالة وتكافؤ الفرص، لجميع الطلبة وخصوصا الطلبة ذوي الإعاقة.</span></p></li>\n<li><p><span dir=\"rtl\">ضمان شمولية الاختبارات ومواءمتها مع مخرجات التعلم للمساق والبرنامج.</span></p></li>\n<li><p><span dir=\"rtl\">صون النزاهة الأكاديمية وأمن الامتحانات في البيئتين الورقية والإلكترونية.</span></p></li>\n<li><p><span dir=\"rtl\">تطوير مهارات أعضاء هيئة التدريس في بناء الاختبارات وتحليل نتائجها.</span></p></li>\n<li><p><span dir=\"rtl\">توفير بيانات موثقة تدعم متطلبات الاعتماد والتحسين المستمر.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">1.3 النطاق</span></h3>\n<p><span dir=\"rtl\">تسري هذه السياسة على جميع أدوات التقييم المحتسبة في العلامة النهائية للمساق، في برامج الدبلوم والبكالوريوس والدراسات العليا، وفي جميع الكليات والفروع. ويشمل ذلك الامتحانات القصيرة والنصفية والنهائية والبديلة، الورقية والإلكترونية.</span></p>\n<h3><span dir=\"rtl\">1.4 التعريفات</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المصطلح</span></th>\n<th><span dir=\"rtl\">التعريف</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">مخرجات التعلم (CLOs)</span></td>\n<td><span dir=\"rtl\">عبارات قابلة للقياس تصف ما يُتوقع من الطالب معرفته أو أداؤه بعد إنهاء المساق</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مخطط الاختبار (Test Blueprint)</span></td>\n<td><span dir=\"rtl\">جدول يربط موضوعات المساق بمستويات التعلم ويحدد عدد الأسئلة وعلاماتها في كل خلية</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">أسئلة الاختيار (Selected-Response)</span></td>\n<td><span dir=\"rtl\">أسئلة يختار فيها الطالب الإجابة من بدائل معطاة: الاختيار من متعدد، الصواب والخطأ، المطابقة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">أسئلة الإنتاج (Constructed-Response)</span></td>\n<td><span dir=\"rtl\">أسئلة يكتب فيها الطالب إجابته بنفسه: الإكمال، الإجابة القصيرة، المقالي المقيد والممتد، حل المسائل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">السؤال المعتمد على سياق</span></td>\n<td><span dir=\"rtl\">مجموعة أسئلة تتبع نصاً أو حالة أو جدولاً أو رسماً مشتركاً</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">سلّم التقدير (Rubric)</span></td>\n<td><span dir=\"rtl\">أداة تحدد معايير التصحيح ومستويات الأداء والعلامة المقابلة لكل مستوى</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">معامل الصعوبة (p)</span></td>\n<td><span dir=\"rtl\">نسبة الطلبة الذين أجابوا عن السؤال إجابة صحيحة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">معامل التمييز (D)</span></td>\n<td><span dir=\"rtl\">قدرة السؤال على التفريق بين مرتفعي التحصيل ومنخفضي التحصيل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الامتحان البديل</span></td>\n<td><span dir=\"rtl\">امتحان يُعقد للطالب بعذر مقبول بدلاً من الامتحان الأصلي، مكافئ له في المستوى والتغطية</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الترتيبات التيسيرية</span></td>\n<td><span dir=\"rtl\">تعديلات في ظروف الامتحان لا تغير ما يقيسه، تُمنح للطلبة ذوي الإعاقة أو الظروف الخاصة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">التدقيق والموازنة (Moderation)</span></td>\n<td><span dir=\"rtl\">مراجعة مستقلة للاختبار أو لعينة من الأوراق المصححة للتحقق من سلامة المعايير واتساقها</span></td>\n</tr>\n</tbody>\n</table></div>\n<h2><span dir=\"rtl\">2. المبادئ الحاكمة ومنظومة التقييم</span></h2>\n<h3><span dir=\"rtl\">2.1 المبادئ الحاكمة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المبدأ</span></th>\n<th><span dir=\"rtl\">المعنى الإجرائي</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">الصدق (Validity)</span></td>\n<td><p><span dir=\"rtl\">أن يقيس الاختبار ما صُمم لقياسه، ويشمل:</span></p>\n<ul>\n<li><p><span dir=\"rtl\">صدق المحتوى (تمثيل كافٍ للموضوعات).</span></p></li>\n<li><p><span dir=\"rtl\">وصدق البناء (قياس المهارة المقصودة لا غيرها).</span></p></li>\n<li><p><span dir=\"rtl\">وسلامة القرارات المبنية على الدرجات.</span></p></li>\n</ul></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الثبات (Reliability)</span></td>\n<td><span dir=\"rtl\">أن تكون النتائج متسقة، سواء بين أسئلة الاختبار أو بين المصححين</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الموضوعية (Objectivity)</span></td>\n<td><span dir=\"rtl\">تقليل أثر الأحكام الشخصية بمعايير تصحيح معلنة وموحدة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العدالة (Fairness)</span></td>\n<td><span dir=\"rtl\">فرص متكافئة للجميع، وخلو الأسئلة من التحيز اللغوي أو الثقافي، والترتيبات التيسيرية لمن يستحقها</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الشمولية (Comprehensiveness)</span></td>\n<td><span dir=\"rtl\">تغطية المخرجات والمحتوى بأوزان تتناسب مع أهميتها وزمن تدريسها</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الشفافية (Transparency)</span></td>\n<td><span dir=\"rtl\">إعلام الطلبة بطبيعة التقييم وأوزانه ومعايير تصحيحه في بداية الفصل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المواءمة (Alignment)</span></td>\n<td><span dir=\"rtl\">توافق أدوات التقييم مع مخرجات المساق وأساليب تدريسه ومخرجات البرنامج</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">قابلية التطبيق (Practicality)</span></td>\n<td><span dir=\"rtl\">أن يكون التقييم ممكناً من حيث الوقت والجهد والكلفة والموارد المتاحة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">النزاهة الأكاديمية (Integrity)</span></td>\n<td><span dir=\"rtl\">أن يعكس التقييم جهد الطالب الفعلي، وأن يُصمم بما يقلل فرص الغش والانتحال</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">2.2 منظومة التقييم المتكاملة</span></h3>\n<p><span dir=\"rtl\">الامتحان النهائي جزء من منظومة أوسع تشمل ثلاثة أنواع من التقييم:</span></p>\n<ul>\n<li><p><span dir=\"rtl\"><strong>التقييم التكويني:</strong> أنشطة قصيرة خلال الفصل غرضها التغذية الراجعة، وقد تكون بعلامة منخفضة أو بلا علامة.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التقييم المستمر:</strong> الامتحانات القصيرة والنصفية والواجبات والتقارير والمشاريع.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التقييم الختامي:</strong> الامتحان النهائي أو المشروع النهائي.</span></p></li>\n</ul>\n<p><span dir=\"rtl\">وتشجع الجامعة <strong>التقييم الأصيل</strong> المرتبط بمواقف مهنية حقيقية، مثل: المشاريع التطبيقية، وملفات الإنجاز، والعروض الشفوية، ودراسات الحالة، والتدريب الميداني، لانسجامه مع الطابع التقني والتطبيقي للجامعة.</span></p>\n<h3><span dir=\"rtl\">2.3 توزيع العلامات</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">لا يتجاوز وزن الامتحان النهائي <strong>40% إلى 50%</strong> من العلامة الكلية للمساق، وفق ما تقره أنظمة الجامعة.</span></p></li>\n<li><p><span dir=\"rtl\">تُوزع علامات التقييم المستمر على <strong>ثلاث أدوات مختلفة على الأقل</strong>، ولا تزيد أي أداة منها على 30% من علامة المساق باستثناء النهائي.</span></p></li>\n<li><p><span dir=\"rtl\">تُعلَن أدوات التقييم وأوزانها ومواعيدها في خطة المساق خلال الأسبوع الأول من الفصل، ولا تُعدَّل إلا بموافقة رئيس القسم وإبلاغ الطلبة.</span></p></li>\n<li><p><span dir=\"rtl\">يُبلَّغ الطلبة بنتائج التقييم المستمر قبل الامتحان النهائي.</span></p></li>\n<li><p><span dir=\"rtl\">في المساقات العملية والمختبرية والميدانية والفنية، يحدد القسم توزيعاً يناسب طبيعة المساق، بشرط أن يكون الأداء العملي هو المكون الأكبر.</span></p></li>\n</ol>\n<h2><span dir=\"rtl\">3. أدوات التقييم وبناء الاختبارات</span></h2>\n<h3><span dir=\"rtl\">3.1 أنواع الأسئلة المعتمدة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><strong><span dir=\"rtl\">الفئة</span></strong></th>\n<th><strong><span dir=\"rtl\">النوع</span></strong></th>\n<th><strong><span dir=\"rtl\">ما يقيسه</span></strong></th>\n<th><strong><span dir=\"rtl\">ضوابط الاستخدام</span></strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">الاختيار</span></td>\n<td><span dir=\"rtl\">الاختيار من متعدد</span></td>\n<td><span dir=\"rtl\">التذكر والفهم والتطبيق والتحليل</span></td>\n<td><span dir=\"rtl\"><mark>أربعة بدائل،</mark> وهو النوع الأساسي في الجزء الموضوعي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الاختيار</span></td>\n<td><span dir=\"rtl\">الصواب والخطأ</span></td>\n<td><span dir=\"rtl\">التمييز بين الحقائق والمفاهيم الخاطئة</span></td>\n<td><span dir=\"rtl\">لا يزيد على 10% من علامة الاختبار بسبب ارتفاع احتمال التخمين (50%)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الاختيار</span></td>\n<td><span dir=\"rtl\">المطابقة</span></td>\n<td><span dir=\"rtl\">الربط بين المصطلحات والتعريفات أو الأسباب والنتائج</span></td>\n<td><span dir=\"rtl\">قائمة متجانسة<mark>، وبدائل أكثر من المقدمات</mark></span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الإنتاج</span></td>\n<td><span dir=\"rtl\">الإكمال</span></td>\n<td><span dir=\"rtl\">استدعاء المصطلحات والقيم</span></td>\n<td><span dir=\"rtl\">إجابة واحدة محددة، وفراغ واحد في آخر العبارة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الإنتاج</span></td>\n<td><span dir=\"rtl\">الإجابة القصيرة</span></td>\n<td><span dir=\"rtl\">التعريف والتعليل الموجز والحساب</span></td>\n<td><span dir=\"rtl\">حدود واضحة للإجابة (عدد النقاط أو الأسطر)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الإنتاج</span></td>\n<td><span dir=\"rtl\">المقالي المقيد</span></td>\n<td><span dir=\"rtl\">المقارنة والتفسير والتطبيق</span></td>\n<td><span dir=\"rtl\">تحديد المهمة ونطاقها، مع سلّم تقدير تحليلي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الإنتاج</span></td>\n<td><span dir=\"rtl\">المقالي الممتد</span></td>\n<td><span dir=\"rtl\">التركيب والنقد وبناء الحجة والإبداع</span></td>\n<td><span dir=\"rtl\">سؤال أو سؤالان في الامتحان مع زمن كافٍ، ولا توجد أسئلة اختيارية بينها</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مركب</span></td>\n<td><span dir=\"rtl\">المعتمد على سياق / دراسة حالة</span></td>\n<td><span dir=\"rtl\">التطبيق والتحليل والتقييم وحل المشكلات</span></td>\n<td><span dir=\"rtl\">أن تتطلب الإجابة استخدام السياق فعلاً، وألا تعتمد الأسئلة على بعضها</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">3.2 التوزيع الاسترشادي بين الأسئلة الموضوعية والإنشائية</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تحسب النسب <strong>من علامة الاختبار</strong>، لا من عدد الأسئلة.</span></p></li>\n<li><p><span dir=\"rtl\">المدى الاسترشادي للمساقات النظرية: <strong>40% إلى 70% أسئلة موضوعية</strong> و<strong>30% إلى 60% أسئلة إنشائية</strong>، والنقطة المرجعية 60% / 40%.</span></p></li>\n<li><p><span dir=\"rtl\">الحاكم الفعلي للتوزيع هو مخطط الاختبار ومستويات المخرجات، لا نوع السؤال. والخروج عن المدى يحتاج مبرراً مكتوباً يعتمده مجلس القسم.</span></p></li>\n<li><p><span dir=\"rtl\">لا يُطبّق هذا التوزيع آلياً على المساقات العملية والمختبرية والفنية ومساقات المشاريع.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">3.3 توزيع مستويات التفكير</span></h3>\n<p><span dir=\"rtl\">تعتمد الجامعة <strong>تصنيف بلوم المعدّل</strong> (Anderson &amp; Krathwohl, 2001) لغةً موحدة لوصف مستويات التعلم. وتكون الأوزان الاسترشادية من علامة الاختبار كما يلي:</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">مستوى المساق</span></th>\n<th><span dir=\"rtl\">التذكر</span></th>\n<th><span dir=\"rtl\">الفهم</span></th>\n<th><span dir=\"rtl\">التطبيق</span></th>\n<th><span dir=\"rtl\">التحليل والتقييم والإبداع</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">مساقات السنة الأولى (متطلبات ومبادئ)</span></td>\n<td><span dir=\"rtl\">لا يزيد عن 40%</span></td>\n<td>25% – 30%</td>\n<td>20% – 25%</td>\n<td>10% – 15%</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مساقات السنة الثانية والثالثة</span></td>\n<td><span dir=\"rtl\">لا يزيد عن 30%</span></td>\n<td>20% – 25%</td>\n<td>25% – 30%</td>\n<td>20% – 25%</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مساقات السنة الرابعة والدراسات العليا</span></td>\n<td><span dir=\"rtl\">لا يزيد عن 20%</span></td>\n<td>15% – 20%</td>\n<td>25% – 30%</td>\n<td><span dir=\"rtl\">30% فأكثر</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">3.4 ضوابط بناء الاختبار</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يُعدّ <strong>مخطط اختبار</strong> لكل امتحان نصفي ونهائي (الملحق أ)، تُحدد فيه أوزان الموضوعات وفق زمن تدريسها وأهميتها.</span></p></li>\n<li><p><span dir=\"rtl\">يرتبط كل سؤال بمخرج تعلم معلن وبمستوى محدد من التصنيف.</span></p></li>\n<li><p><span dir=\"rtl\">تُصاغ الأسئلة الموضوعية وفق قواعد موحدة (الملحق ب)، أهمها:</span></p>\n<ul>\n<li><p><span dir=\"rtl\">جذع يطرح مشكلة واضحة مكتملة يمكن فهمها دون قراءة البدائل.</span></p></li>\n<li><p><span dir=\"rtl\">إجابة واحدة صحيحة بلا جدال، ومموهات معقولة مبنية على أخطاء شائعة.</span></p></li>\n<li><p><span dir=\"rtl\">بدائل متجانسة متقاربة الطول، وتجنب «جميع ما سبق» و«لا شيء مما سبق».</span></p></li>\n<li><p><span dir=\"rtl\">تجنب النفي، وإن استُخدم يُبرز بخط واضح.</span></p></li>\n<li><p><span dir=\"rtl\">توزيع مواقع الإجابات الصحيحة بالتساوي تقريباً بين البدائل.</span></p></li>\n</ul></li>\n<li><p><span dir=\"rtl\">تُصاغ الأسئلة الإنشائية بأفعال إجرائية محددة (قارن، علّل، انقد، صمّم)، لا بأفعال عامة مثل «اكتب ما تعرفه»، مع بيان العلامة والنطاق المطلوب.</span></p></li>\n<li><p><span dir=\"rtl\">يتناسب حجم الاختبار مع زمنه. المعيار الاسترشادي: من دقيقة إلى دقيقة ونصف لسؤال الاختيار من متعدد، ونصف دقيقة للصواب والخطأ، ودقيقتان إلى ثلاث لكل علامة في المقالي. ويُفترض أن ينهي 90% من الطلبة الاختبار ضمن الوقت.</span></p></li>\n<li><p><span dir=\"rtl\">تتضمن ورقة الامتحان غلافاً موحداً (الملحق و) فيه التعليمات والزمن وعدد الصفحات وعلامة كل سؤال.</span></p></li>\n<li><p><span dir=\"rtl\">لا تزيد نسبة الأسئلة المكررة حرفياً من امتحان الفصل السابق على <strong>30%</strong>.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">3.5 مراجعة الاختبار واعتماده قبل التطبيق</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يُسلَّم الامتحان النهائي مع مخططه ونموذج إجابته إلى لجنة القسم قبل موعده بأسبوعين على الأقل.</span></p></li>\n<li><p><span dir=\"rtl\">تراجع اللجنة الامتحان وفق قائمة التحقق (الملحق ج)، ولها أن تطلب تعديلات موثقة.</span></p></li>\n<li><p><span dir=\"rtl\">في المساقات متعددة الشُعب يكون الامتحان موحداً، يعده فريق المساق بإشراف منسق.</span></p></li>\n<li><p><span dir=\"rtl\">تُعرض امتحانات مساقات التخرج أو عينة منها على <strong>ممتحن خارجي</strong> مرة كل دورة مراجعة للبرنامج.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">3.6 بنك الأسئلة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يُبنى بنك أسئلة للمساقات المشتركة ومتعددة الشُعب أولاً، ثم يُعمم تدريجياً.</span></p></li>\n<li><p><span dir=\"rtl\">يُرمز كل سؤال بالموضوع والمخرج والمستوى والنوع، مع معاملات صعوبته وتمييزه وتاريخ استخدامه.</span></p></li>\n<li><p><span dir=\"rtl\">يُضاف إلى البنك كل فصل ما لا يقل عن <strong>20%</strong> أسئلة جديدة، وتُستبعد الأسئلة التي تثبت ضعف خصائصها.</span></p></li>\n<li><p><span dir=\"rtl\">تُحفظ البنوك على نظام مؤمن بصلاحيات محددة وسجل دخول.</span></p></li>\n</ol>\n<h2><span dir=\"rtl\">4. إدارة الامتحانات وأمنها والنزاهة والعدالة</span></h2>\n<h3><span dir=\"rtl\">4.1 الجدولة والإدارة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يُعلَن جدول الامتحانات النهائية قبل بدايتها بثلاثة أسابيع على الأقل.</span></p></li>\n<li><p><span dir=\"rtl\">لا يُكلَّف الطالب بأكثر من امتحانين نهائيين في اليوم الواحد، ويحق له طلب التعديل عند التعارض.</span></p></li>\n<li><p><span dir=\"rtl\">يُعقد <strong>الامتحان البديل</strong> لأصحاب الأعذار المقبولة وفق أنظمة الجامعة، ويكون مكافئاً للأصلي بالمخطط نفسه وبأسئلة مختلفة.</span></p></li>\n<li><p><span dir=\"rtl\">تضع الجامعة خطة بديلة للظروف الطارئة التي تمنع الوصول إلى الحرم الجامعي، تحدد بدائل التقييم (امتحان إلكتروني، مشروع، امتحان شفوي عن بُعد) وضوابط التحول إليها.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">4.2 أمن الامتحانات</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تبقى أسئلة الامتحان سرية في جميع مراحل الإعداد والمراجعة والطباعة والحفظ والنقل.</span></p></li>\n<li><p><span dir=\"rtl\">تتم الطباعة في مكان مخصص ومؤمن، وتُحفظ الأوراق في مغلفات مختومة حتى موعد الامتحان.</span></p></li>\n<li><p><span dir=\"rtl\">تُستخدم <strong>نماذج متعددة</strong> للامتحان في القاعات المزدحمة، بتغيير ترتيب الأسئلة والبدائل مع المحافظة على تكافؤ المحتوى.</span></p></li>\n<li><p><span dir=\"rtl\">تُحدد نسبة المراقبة بمراقب واحد لكل 25 إلى 30 طالباً، ولا يقل عدد المراقبين عن اثنين في أي قاعة.</span></p></li>\n<li><p><span dir=\"rtl\">يُعدّ المراقب الرئيس تقريراً موجزاً بالغياب والملاحظات والمخالفات.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">4.3 الامتحانات الإلكترونية</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تُعقد على المنصة الرسمية المعتمدة في الجامعة، في مختبرات مراقبة متى أمكن.</span></p></li>\n<li><p><span dir=\"rtl\">يُفعّل الترتيب العشوائي للأسئلة والبدائل، والسحب من بنك الأسئلة بما يحفظ توازن المخطط، والمتصفح المؤمن عند الحاجة.</span></p></li>\n<li><p><span dir=\"rtl\">يُجرى اختبار تجريبي للمنصة والأسئلة قبل الموعد، وامتحان تجريبي للطلبة غير المتمرسين على النظام.</span></p></li>\n<li><p><span dir=\"rtl\">تُوثّق خطة طوارئ للأعطال التقنية وانقطاع الكهرباء أو الشبكة، تحدد تعويض الوقت وإعادة الامتحان.</span></p></li>\n<li><p><span dir=\"rtl\">تُحفظ بيانات الطلبة وإجاباتهم وفق ضوابط حماية البيانات، ولا يطلع عليها إلا المخولون.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">4.4 النزاهة الأكاديمية</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تُعرَّف المخالفات (الغش، الانتحال، انتحال الشخصية، المساعدة غير المشروعة، الاستخدام غير المصرح به لأدوات الذكاء الاصطناعي) وتُعالَج وفق أنظمة التأديب المعمول بها في الجامعة.</span></p></li>\n<li><p><span dir=\"rtl\">يُوقّع الطالب على إقرار نزاهة عند تسليم المشاريع والأعمال المنزلية.</span></p></li>\n<li><p><span dir=\"rtl\">تُعامَل الحالات المشتبه بها بإجراءات موثقة تضمن حق الطالب في الاستماع إليه قبل القرار.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">4.5 الذكاء الاصطناعي التوليدي في التقييم</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يحدد عضو هيئة التدريس لكل أداة تقييم مستوى الاستخدام المسموح، ويعلنه في خطة المساق وفي تعليمات المهمة:</span></p></li>\n</ol>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المستوى</span></th>\n<th><span dir=\"rtl\">الوصف</span></th>\n<th><span dir=\"rtl\">أمثلة مناسبة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">0 – ممنوع</span></td>\n<td><span dir=\"rtl\">لا يُسمح بأي استخدام</span></td>\n<td><span dir=\"rtl\">الامتحانات الصفية المراقبة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">1 – مساند محدود</span></td>\n<td><span dir=\"rtl\">لتوليد الأفكار أو التدقيق اللغوي فقط، مع الإفصاح</span></td>\n<td><span dir=\"rtl\">التقارير والمقالات</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">2 – مدمج بإفصاح</span></td>\n<td><span dir=\"rtl\">مسموح باستخدام موثق ويُقيَّم توظيفه النقدي</span></td>\n<td><span dir=\"rtl\">مشاريع البرمجة والتصميم</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">3 – جزء من المهمة</span></td>\n<td><span dir=\"rtl\">استخدام الأداة هو المهارة المقاسة</span></td>\n<td><span dir=\"rtl\">مساقات الذكاء الاصطناعي وتحليل البيانات</span></td>\n</tr>\n</tbody>\n</table></div>\n<ol start=\"2\" type=\"1\">\n<li><p><span dir=\"rtl\">تُصمم المهام غير المراقبة بما يقلل قابلية إنجازها آلياً: ربطها ببيانات أو سياق محلي، وتسليمها على مراحل، ومناقشة شفوية قصيرة للعمل المقدم.</span></p></li>\n<li><p><span dir=\"rtl\">لا تُعتمد نتائج أدوات كشف النصوص المولّدة آلياً دليلاً وحيداً للإدانة، بسبب محدودية دقتها.</span></p></li>\n<li><p><span dir=\"rtl\">لا تُرفع أعمال الطلبة أو بياناتهم إلى أدوات خارجية غير معتمدة من الجامعة.</span></p></li>\n<li><p><span dir=\"rtl\">يجوز لعضو هيئة التدريس الاستعانة بالذكاء الاصطناعي في صياغة مسودات الأسئلة، على أن يراجعها ويتحمل مسؤولية صحتها وسريتها.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">4.6 العدالة والترتيبات التيسيرية</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يحق للطلبة ذوي الإعاقة أو الظروف الصحية الموثقة طلب ترتيبات تيسيرية، مثل: زمن إضافي (25% إلى 50%)، أو خط مكبر، أو قارئ، أو كاتب، أو قاعة مستقلة، أو امتحان إلكتروني.</span></p></li>\n<li><p><span dir=\"rtl\">يُقدَّم الطلب إلى عمادة شؤون الطلبة قبل فترة الامتحانات، وتُبلَّغ الأقسام بالترتيبات المعتمدة مع الحفاظ على سرية الحالة (الملحق ز).</span></p></li>\n<li><p><span dir=\"rtl\">لا تغيّر الترتيبات التيسيرية ما يقيسه الامتحان ولا مستواه.</span></p></li>\n<li><p><span dir=\"rtl\">تُراجع صياغة الأسئلة لتخلو من التحيز اللغوي أو الثقافي أو الاجتماعي، ومن التعقيد اللغوي غير المرتبط بالمحتوى.</span></p></li>\n<li><p><span dir=\"rtl\">تُراعى مبادئ <strong>التصميم الشامل للتعلم (UDL)</strong> بتنويع أدوات التقييم على مدار الفصل.</span></p></li>\n</ol>\n<h2><span dir=\"rtl\">5. التصحيح والنتائج والتحليل الإحصائي والتظلمات</span></h2>\n<h3><span dir=\"rtl\">5.1 ضوابط تصحيح الأسئلة الإنشائية</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يُعدّ نموذج إجابة و<strong>سلّم تقدير</strong> تفصيلي قبل بدء التصحيح، تحليلي للأسئلة ذات العناصر المتعددة، وكلي للأسئلة القصيرة ذات الطابع العام.</span></p></li>\n<li><p><span dir=\"rtl\">يُجرَب السلّم على عينة من 5 إلى 10 أوراق ويُعدَّل قبل التصحيح الفعلي، ولا يُغيَّر بعد البدء إلا مع إعادة تصحيح ما سبق.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التصحيح الأفقي:</strong> يُصحَّح السؤال الواحد لجميع الطلبة قبل الانتقال إلى السؤال التالي، مع تغيير ترتيب الأوراق بين الأسئلة.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التصحيح بإخفاء الهوية</strong> متى أمكن، باستخدام الرقم الجامعي أو رمز بدلاً من الاسم.</span></p></li>\n<li><p><span dir=\"rtl\">في المساقات متعددة الشُعب، يصحح كل عضو سؤالاً أو أكثر لجميع الشُعب.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التصحيح المزدوج الإلزامي</strong> في الحالات الآتية:</span></p>\n<ul>\n<li><p><span dir=\"rtl\">الأسئلة التي تزيد علامتها على 15% من علامة الامتحان.</span></p></li>\n<li><p><span dir=\"rtl\">عينة عشوائية لا تقل عن 10% من الأوراق في الامتحانات النهائية.</span></p></li>\n<li><p><span dir=\"rtl\">مشاريع التخرج والرسائل.</span></p></li>\n<li><p><span dir=\"rtl\">الأوراق الواقعة على حدود النجاح (علامتان دون الحد أو فوقه).</span></p></li>\n</ul></li>\n<li><p><span dir=\"rtl\">إذا تجاوز الفرق بين المصححَين <strong>15%</strong> من علامة السؤال، يُحال إلى مصحح ثالث، وإلا يُؤخذ المتوسط.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">5.2 رصد النتائج وتحديد علامة النجاح</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تُرصد نتائج الامتحانات النصفية خلال أسبوعين، والنهائية ضمن الموعد الذي تحدده عمادة القبول والتسجيل.</span></p></li>\n<li><p><span dir=\"rtl\">تعتمد الجامعة <strong>التقييم المحكي</strong>: يُحكم على أداء الطالب بمعايير محددة مسبقاً، لا بمقارنته بزملائه.</span></p></li>\n<li><p><span dir=\"rtl\">لا يجوز تعديل العلامات جماعياً (الرفع أو التدريج) إلا بمبرر موثق، كثبوت خلل في أسئلة محددة، وبموافقة مجلس القسم والعميد، ويُطبق بمعادلة واحدة على جميع الطلبة.</span></p></li>\n<li><p><span dir=\"rtl\">في الامتحانات عالية المخاطر (الامتحانات الشاملة، امتحانات الكفاية) يُحدَّد حد النجاح بطرق معيارية مثل طريقة أنغوف (Angoff).</span></p></li>\n<li><p><span dir=\"rtl\"><strong>مؤشرات إنذار</strong> تستدعي مراجعة رئيس القسم قبل اعتماد النتائج: نسبة رسوب تزيد على 30%، أو نسبة تقدير «ممتاز» تزيد على 40%، أو فرق كبير بين متوسطات شُعب المساق نفسه. والمراجعة لا تعني بالضرورة تعديل النتائج.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">5.3 التحليل الإحصائي لجودة الاختبارات</span></h3>\n<p><span dir=\"rtl\">يُحلَّل كل امتحان نهائي موضوعي يتقدم له 30 طالباً فأكثر، ويُرفق التقرير بملف المساق (الملحق هـ). وتُعتمد المحكّات الاسترشادية الآتية:</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المؤشر</span></th>\n<th><span dir=\"rtl\">المحكّ الاسترشادي</span></th>\n<th><span dir=\"rtl\">الإجراء عند الخروج عنه</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">معامل الصعوبة (p)</span></td>\n<td><span dir=\"rtl\">المقبول 0.30 – 0.80، والمثالي 0.50 – 0.70</span></td>\n<td><span dir=\"rtl\">مراجعة الصياغة ومدى تغطية الموضوع في التدريس</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">معامل التمييز (D)</span></td>\n<td><span dir=\"rtl\">ممتاز ≥ 0.40 · جيد 0.30 – 0.39 · يُراجع 0.20 – 0.29 · ضعيف &lt; 0.20</span></td>\n<td><span dir=\"rtl\">الضعيف يُعدَّل، والسالب يُفحص مفتاحه فوراً</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">فاعلية المموهات</span></td>\n<td><span dir=\"rtl\">يختار كل مموه 5% من الطلبة على الأقل، ويجذب الفئة الدنيا أكثر من العليا</span></td>\n<td><span dir=\"rtl\">استبدال المموه غير الفاعل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ثبات الاختبار (KR-20 / ألفا كرونباخ)</span></td>\n<td><span dir=\"rtl\">≥ 0.70 للاختبارات الصفية · ≥ 0.80 للاختبارات عالية المخاطر</span></td>\n<td><span dir=\"rtl\">زيادة عدد الأسئلة الجيدة ومراجعة الضعيفة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ثبات المصححين (كابا / ICC)</span></td>\n<td><span dir=\"rtl\">≥ 0.70 في العينة المصححة مرتين</span></td>\n<td><span dir=\"rtl\">تدقيق السلّم وجلسة معايرة بين المصححين</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الخطأ المعياري للقياس (SEM)</span></td>\n<td><span dir=\"rtl\">يُحسب ويُراعى في الحالات الحدّية قرب النجاح</span></td>\n<td><span dir=\"rtl\">مراجعة أوراق الحالات الحدّية</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>معالجة الأسئلة المعيبة بعد الامتحان:</strong> إذا ثبت خلل في سؤال (مفتاح خاطئ، أكثر من إجابة صحيحة، غموض، محتوى لم يُدرَّس)، يقرر مجلس القسم بتنسيب من منسق المساق أحد الإجراءات الآتية، ويُطبَّق على جميع الطلبة ويُوثَّق:</span></p>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تصحيح المفتاح وإعادة الرصد إذا كان الخطأ في المفتاح فقط.</span></p></li>\n<li><p><span dir=\"rtl\">قبول أكثر من إجابة إذا كانت للسؤال أكثر من إجابة صحيحة علمياً.</span></p></li>\n<li><p><span dir=\"rtl\">حذف السؤال وإعادة احتساب العلامة نسبياً من باقي الأسئلة إذا كان الخلل جوهرياً.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">5.4 التغذية الراجعة للطلبة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يحق للطالب الاطلاع على ورقة إجابته في الامتحانات النصفية والأعمال الفصلية، مع ملاحظات مكتوبة تبين نقاط القوة والضعف.</span></p></li>\n<li><p><span dir=\"rtl\">يُناقش الامتحان النصفي في جلسة مراجعة بعد إعلان نتائجه.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">5.5 التظلمات</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يحق للطالب التظلم من علامة الامتحان النهائي خلال المدة التي تحددها أنظمة الجامعة من إعلان النتيجة، بنموذج موحد (الملحق ح).</span></p></li>\n<li><p><span dir=\"rtl\">يشمل التظلم: الخطأ في جمع العلامات أو رصدها، والأسئلة غير المصححة، ومخالفة التصحيح للسلّم المعتمد.</span></p></li>\n<li><p><span dir=\"rtl\">تنظر في التظلم لجنة من عضوين على الأقل ليس بينهما مدرس المساق، وتبت فيه خلال أسبوعين.</span></p></li>\n<li><p><span dir=\"rtl\">قد تؤدي المراجعة إلى رفع العلامة أو تثبيتها أو خفضها، ويُبلَّغ الطالب بالنتيجة وأسبابها كتابياً.</span></p></li>\n</ol>\n<h2><span dir=\"rtl\">6. الأدوار والتدريب والتوثيق والمتابعة</span></h2>\n<h3><span dir=\"rtl\">6.1 الأدوار والمسؤوليات</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الجهة</span></th>\n<th><span dir=\"rtl\">المسؤوليات الرئيسية</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">عضو هيئة التدريس</span></td>\n<td><span dir=\"rtl\">إعداد المخطط والأسئلة ونموذج الإجابة والسلّم، والتصحيح والرصد في الموعد، وإعداد تقرير التحليل والتغذية الراجعة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">منسق المساق متعدد الشُعب</span></td>\n<td><span dir=\"rtl\">توحيد الامتحان والسلّم، وتوزيع التصحيح الأفقي، وموازنة النتائج بين الشُعب</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">رئيس القسم ولجنة الامتحانات فيه</span></td>\n<td><span dir=\"rtl\">مراجعة الامتحانات واعتمادها، ومتابعة مؤشرات الإنذار، والبت في الأسئلة المعيبة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">عميد الكلية</span></td>\n<td><span dir=\"rtl\">الإشراف على التطبيق في الكلية، واعتماد أي تعديل جماعي للعلامات، ورفع التقرير الفصلي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">اللجنة الجامعية للقياس والتقويم</span></td>\n<td><span dir=\"rtl\">إعداد الأدلة والنماذج، والتدريب، والتدقيق على عينات من الامتحانات، والتقرير السنوي لمجلس الجامعة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">وحدة الجودة والتطوير</span></td>\n<td><span dir=\"rtl\">متابعة مؤشرات الأداء وربطها بمتطلبات الاعتماد</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">دائرة التعلم الإلكتروني وتكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">جاهزية منصة الامتحانات وأمنها وحماية بياناتها والدعم الفني</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الطالب</span></td>\n<td><span dir=\"rtl\">الالتزام بالنزاهة والتعليمات، والإفصاح عن استخدام أدوات الذكاء الاصطناعي، واتباع إجراءات التظلم</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">6.2 التدريب والتطوير المهني</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يلتحق أعضاء هيئة التدريس الجدد إلزامياً ببرنامج تدريبي في بناء الاختبارات لا يقل عن <strong>12 ساعة</strong> خلال سنتهم الأولى.</span></p></li>\n<li><p><span dir=\"rtl\">يلتحق بقية الأعضاء بـ <strong>6 ساعات على الأقل كل سنتين</strong> في موضوعات القياس والتقويم.</span></p></li>\n<li><p><span dir=\"rtl\">يُعتمد <strong>الدليل التدريبي لبناء الاختبارات</strong> المرافق مرجعاً للبرنامج.</span></p></li>\n<li><p><span dir=\"rtl\">يُؤخذ الالتزام بالسياسة بعين الاعتبار في تقييم الأداء السنوي لأعضاء هيئة التدريس.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">6.3 التوثيق والأرشفة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">يتضمن <strong>ملف المساق</strong> لكل فصل: الخطة، ونسخ الامتحانات ومخططاتها ونماذج إجابتها وسلالمها، وعينات من أوراق الطلبة (مرتفع ومتوسط ومنخفض)، وتقرير التحليل، وتقرير المساق.</span></p></li>\n<li><p><span dir=\"rtl\">تُحفظ أوراق الامتحانات النهائية <strong>فصلاً دراسياً كاملاً على الأقل</strong> بعد انتهاء مهلة التظلم، ويُحفظ ملف المساق طوال دورة الاعتماد.</span></p></li>\n<li><p><span dir=\"rtl\">يُفضَّل الحفظ الإلكتروني المؤمن لملفات المساقات.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">6.4 مؤشرات أداء السياسة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المؤشر</span></th>\n<th><span dir=\"rtl\">المستهدف بعد سنتين</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">نسبة المساقات ذات مخطط اختبار معتمد</span></td>\n<td>100%</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">متوسط معامل ثبات الامتحانات النهائية الموضوعية</span></td>\n<td><span dir=\"rtl\">0.70 فأكثر</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">نسبة الأسئلة ذات تمييز 0.20 فأكثر</span></td>\n<td><span dir=\"rtl\">80% فأكثر</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">نسبة أسئلة المستويات العليا في مساقات السنوات المتقدمة</span></td>\n<td><span dir=\"rtl\">ضمن الأوزان في البند 3.3</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">نسبة التظلمات المقبولة من مجموع التظلمات</span></td>\n<td><span dir=\"rtl\">انخفاض سنوي مستمر</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">نسبة أعضاء هيئة التدريس المدربين</span></td>\n<td><span dir=\"rtl\">90% فأكثر</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">رضا الطلبة عن عدالة التقييم (استبانة فصلية)</span></td>\n<td><span dir=\"rtl\">75% فأكثر</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">6.5 آليات التنفيذ</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">تشكيل <strong>اللجنة الجامعية للقياس والتقويم</strong> خلال شهر من اعتماد السياسة، ولجان امتحانات في الأقسام.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التطبيق التجريبي</strong> في فصل دراسي واحد على مساقين إلى ثلاثة من كل كلية، تشمل مساقات علمية وإنسانية ومساقات متعددة الشُعب.</span></p></li>\n<li><p><span dir=\"rtl\">تقييم التجربة وتعديل السياسة وملاحقها، ثم التعميم التدريجي في العام الدراسي التالي.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">6.6 النفاذ والمراجعة والمراجع ذات الصلة</span></h3>\n<ul>\n<li><p><span dir=\"rtl\"><strong>جهة الاعتماد:</strong> مجلس الجامعة، بتنسيب من مجلس العمداء.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>النفاذ:</strong> من تاريخ الاعتماد، وفق الخطة المرحلية في البند 6.5.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>المراجعة:</strong> كل سنتين أو عند الحاجة، بناءً على تقرير اللجنة الجامعية.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>التفسير:</strong> يرجع التفسير إلى مجلس العمداء، ويُعمل بأنظمة الجامعة النافذة فيما لم يرد به نص.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>الوثائق ذات الصلة:</strong> أنظمة الدراسة والامتحانات، نظام التأديب الطلابي، معايير هيئة الاعتماد والجودة الفلسطينية، الدليل التدريبي لبناء الاختبارات.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>المراجع العلمية:</strong> AERA, APA &amp; NCME (2014), <em>Standards for Educational and Psychological Testing</em>؛ Anderson &amp; Krathwohl (2001), <em>A Taxonomy for Learning, Teaching, and Assessing</em>؛ Haladyna &amp; Rodriguez (2013), <em>Developing and Validating Test Items</em>.</span></p></li>\n</ul>\n<h2><span dir=\"rtl\">7. الملاحق والنماذج</span></h2>\n<p><span dir=\"rtl\">الأمثلة المحلولة لكل نموذج موجودة في الدليل التدريبي المرافق.</span></p>\n<h3><span dir=\"rtl\">الملحق (أ): نموذج مخطط الاختبار</span></h3>\n<p><span dir=\"rtl\">المساق: ............ الرمز: ............ الفصل: ............ نوع الامتحان: ............ العلامة الكلية: ............ الزمن: ............</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الموضوع / الوحدة</span></th>\n<th><span dir=\"rtl\">المخرج المرتبط</span></th>\n<th><span dir=\"rtl\">ساعات التدريس</span></th>\n<th><span dir=\"rtl\">الوزن %</span></th>\n<th><span dir=\"rtl\">تذكر</span></th>\n<th><span dir=\"rtl\">فهم</span></th>\n<th><span dir=\"rtl\">تطبيق</span></th>\n<th><span dir=\"rtl\">تحليل / تقييم / إبداع</span></th>\n<th><span dir=\"rtl\">العلامة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><strong><span dir=\"rtl\">المجموع</span></strong></td>\n<td></td>\n<td></td>\n<td>100%</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">في كل خلية يُكتب عدد الأسئلة ونوعها وعلامتها، مثل: «3 اختيار من متعدد / 3 علامات».</span></p>\n<h3><span dir=\"rtl\">الملحق (ب): قائمة تحقق من جودة سؤال الاختيار من متعدد</span></h3>\n<ul>\n<li><p><span dir=\"rtl\">☐ يقيس السؤال مخرجاً محدداً ومستوى محدداً في المخطط.</span></p></li>\n<li><p><span dir=\"rtl\">☐ الجذع مشكلة واضحة يمكن الإجابة عنها قبل قراءة البدائل.</span></p></li>\n<li><p><span dir=\"rtl\">☐ الجذع خالٍ من المعلومات الزائدة غير المقصودة.</span></p></li>\n<li><p><span dir=\"rtl\">☐ لا نفي في الجذع، أو أن النفي مبرز بخط واضح.</span></p></li>\n<li><p><span dir=\"rtl\">☐ إجابة واحدة صحيحة بلا جدال.</span></p></li>\n<li><p><span dir=\"rtl\">☐ المموهات معقولة ومبنية على أخطاء شائعة.</span></p></li>\n<li><p><span dir=\"rtl\">☐ البدائل متجانسة ومتقاربة الطول ومتسقة نحوياً مع الجذع.</span></p></li>\n<li><p><span dir=\"rtl\">☐ لا تستخدم «جميع ما سبق» أو «لا شيء مما سبق».</span></p></li>\n<li><p><span dir=\"rtl\">☐ لا توجد ألفاظ تلميحية تشير إلى الإجابة (دائماً، أبداً، تكرار كلمة من الجذع).</span></p></li>\n<li><p><span dir=\"rtl\">☐ السؤال مستقل عن غيره ولا يكشف إجابة سؤال آخر.</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">الملحق (ج): قائمة تحقق لجنة القسم لمراجعة ورقة الامتحان</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">البند</span></th>\n<th><span dir=\"rtl\">متحقق</span></th>\n<th><span dir=\"rtl\">غير متحقق</span></th>\n<th><span dir=\"rtl\">ملاحظات</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">مخطط الاختبار مرفق والأسئلة مطابقة له</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">التوزيع بين الموضوعي والإنشائي ضمن المدى أو مبرر</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مستويات التفكير ضمن الأوزان المعتمدة</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الصياغة واضحة وخالية من الأخطاء العلمية واللغوية</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الزمن متناسب مع عدد الأسئلة ونوعها</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلامات موضحة لكل سؤال ومجموعها صحيح</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">نموذج الإجابة وسلالم التقدير مرفقة</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">نسبة الأسئلة المكررة من الفصل السابق لا تتجاوز 30%</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الغلاف والتعليمات وفق النموذج الموحد</span></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">قرار اللجنة: معتمد / معتمد بعد التعديل / يُعاد إعداده — التوقيع: ............ التاريخ: ............</span></p>\n<h3><span dir=\"rtl\">الملحق (د): نموذج سلّم تقدير تحليلي</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المعيار (العلامة)</span></th>\n<th><span dir=\"rtl\">ممتاز (4)</span></th>\n<th><span dir=\"rtl\">جيد (3)</span></th>\n<th><span dir=\"rtl\">مقبول (2)</span></th>\n<th><span dir=\"rtl\">ضعيف (1)</span></th>\n<th><span dir=\"rtl\">غير موجود (0)</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">المعيار الأول</span></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المعيار الثاني</span></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المعيار الثالث</span></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">يُوصف في كل خلية ما يبدو عليه الأداء فعلاً بلغة قابلة للملاحظة، لا بكلمات عامة مثل «جيد جداً».</span></p>\n<h3><span dir=\"rtl\">الملحق (هـ): نموذج تقرير التحليل الإحصائي للاختبار</span></h3>\n<p><span dir=\"rtl\">المساق: ............ عدد الممتحنين: ............ المتوسط: ............ الانحراف المعياري: ............ معامل الثبات: ............ نسبة النجاح: ............</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">رقم السؤال</span></th>\n<th><span dir=\"rtl\">المخرج</span></th>\n<th><span dir=\"rtl\">المستوى</span></th>\n<th><span dir=\"rtl\">الصعوبة (p)</span></th>\n<th><span dir=\"rtl\">التمييز (D)</span></th>\n<th><span dir=\"rtl\">المموهات غير الفاعلة</span></th>\n<th><span dir=\"rtl\">القرار (يُبقى / يُعدَّل / يُحذف)</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">ملاحظات للتحسين في التدريس والاختبارات اللاحقة: ............</span></p>\n<h3><span dir=\"rtl\">الملحق (و): الغلاف الموحد لورقة الامتحان</span></h3>\n<ul>\n<li><p><span dir=\"rtl\">شعار الجامعة، الكلية، القسم، اسم المساق ورمزه، الفصل والعام الدراسي.</span></p></li>\n<li><p><span dir=\"rtl\">نوع الامتحان، التاريخ، الزمن، عدد الصفحات، العلامة الكلية، رمز النموذج.</span></p></li>\n<li><p><span dir=\"rtl\">الرقم الجامعي، والشعبة، والاسم في جزء قابل للفصل عند التصحيح بإخفاء الهوية.</span></p></li>\n<li><p><span dir=\"rtl\">التعليمات: عدد الأسئلة وأقسامها، ومكان الإجابة، والأدوات المسموحة (آلة حاسبة، جداول)، ومستوى استخدام الذكاء الاصطناعي، والتذكير بالنزاهة.</span></p></li>\n<li><p><span dir=\"rtl\">جدول رصد العلامات لكل سؤال (للمصحح).</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">الملحق (ز): نموذج طلب ترتيبات تيسيرية</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">البيان</span></th>\n<th><span dir=\"rtl\">التعبئة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">اسم الطالب ورقمه الجامعي</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الكلية والتخصص</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المساقات المعنية</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الترتيب المطلوب (زمن إضافي، خط مكبر، قارئ، كاتب، قاعة مستقلة، غير ذلك)</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الوثائق الداعمة المرفقة</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">قرار عمادة شؤون الطلبة ومدة سريانه</span></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">الملحق (ح): نموذج التظلم من العلامة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">البيان</span></th>\n<th><span dir=\"rtl\">التعبئة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">اسم الطالب ورقمه الجامعي</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المساق والشعبة واسم المدرس</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلامة المعلنة</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">أسباب التظلم: خطأ جمع / سؤال غير مصحح / مخالفة السلّم / غير ذلك</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">تاريخ تقديم الطلب</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">قرار اللجنة والعلامة بعد المراجعة والأسباب</span></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">تواقيع أعضاء اللجنة</span></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n";
